CREATE OR REPLACE FUNCTION public.staff_partner_document_allowed(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.partner_applications a WHERE public.staff_application_allowed(a.id) AND (_path=a.cnic_image_url OR _path=a.shop_image_url OR _path=a.extra->>'cnic_back_url' OR _path=a.extra->>'selfie_url' OR _path=a.extra->>'cheque_path')) OR EXISTS(SELECT 1 FROM public.rider_verifications v JOIN public.partner_applications a ON a.id=v.application_id WHERE public.staff_application_allowed(a.id) AND _path IN (v.front_url,v.back_url,v.selfie_url)) OR EXISTS(SELECT 1 FROM public.rider_remittances r WHERE public.staff_rider_allowed('finance',r.rider_id) AND r.receipt_url=_path) $$;
REVOKE ALL ON FUNCTION public.staff_partner_document_allowed(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.staff_partner_document_allowed(text) TO authenticated,service_role;
ALTER POLICY "Users read own partner docs" ON storage.objects USING(bucket_id='partner-documents' AND (split_part(name,'/',1)=auth.uid()::text OR public.has_role(auth.uid(),'admin') OR public.staff_partner_document_allowed(name)));
CREATE POLICY "Finance upload scoped vendor receipt" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='payout-receipts' AND CASE WHEN split_part(name,'/',1) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN public.staff_vendor_allowed(split_part(name,'/',1)::uuid) ELSE false END);
CREATE POLICY "Finance read scoped vendor receipts" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='payout-receipts' AND CASE WHEN split_part(name,'/',1) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN public.staff_vendor_allowed(split_part(name,'/',1)::uuid) ELSE false END);
CREATE POLICY "Finance clean own receipt upload" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='payout-receipts' AND owner_id=auth.uid()::text AND CASE WHEN split_part(name,'/',1) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN public.staff_vendor_allowed(split_part(name,'/',1)::uuid) ELSE false END);
CREATE OR REPLACE FUNCTION public.staff_list_services() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') $$;
REVOKE ALL ON FUNCTION public.staff_list_services() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE d text; BEGIN
 SELECT pg_get_functiondef('public.guard_staff_record_fields()'::regprocedure) INTO d;
 d:=replace(d,'IF auth.uid() IS NULL OR public.has_role(auth.uid(),''admin'') THEN RETURN NEW; END IF;','IF auth.uid() IS NULL OR public.has_role(auth.uid(),''admin'') OR (TG_TABLE_NAME=''riders'' AND (coalesce(current_setting(''app.bypass_rider_guard'',true),'''')=''on'' OR coalesce(current_setting(''app.bypass_ledger_guard'',true),'''')=''on'')) THEN RETURN NEW; END IF;'); EXECUTE d;
END $$;